
WITH new_slides AS (
  SELECT
    '<div style="box-sizing:border-box;width:100%;height:100%;margin:0;padding:34px 44px 32px;border-radius:18px;overflow:hidden;border:1px solid #22c55e;box-shadow:0 0 0 1px rgba(34,197,94,.08),0 8px 24px -12px rgba(34,197,94,.25);font-family:Inter,system-ui,sans-serif;background:linear-gradient(180deg,#ffffff 0%,#f0fdf4 100%);color:#0f172a;display:flex;flex-direction:column;gap:18px;position:relative;">
  <div style="display:inline-flex;align-items:center;gap:6px;background:#16a34a;color:#fff;padding:6px 14px;border-radius:999px;font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;width:max-content;"><span style="width:6px;height:6px;border-radius:50%;background:#fff;opacity:.9;"></span>Impacto Operacional</div>
  <div style="display:flex;flex-direction:column;gap:6px;">
    <h2 style="font-size:30px;margin:0;font-weight:900;color:#064e3b;letter-spacing:0;line-height:1.08;text-transform:uppercase;max-width:900px;">Mais controle, previsibilidade e eficiência para sua operação de <span style="color:#16a34a;">vendas públicas.</span></h2>
    <div style="height:3px;width:64px;background:#22c55e;border-radius:3px;"></div>
  </div>
  <div style="flex:1;min-height:0;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px;align-items:stretch;">
    <div style="min-width:0;display:flex;flex-direction:column;justify-content:center;gap:10px;">
      <p style="margin:0;font-size:14px;line-height:1.55;color:#334155;">Ao estruturar informações, processos e acompanhamento operacional em uma única plataforma, empresas passam a operar com mais organização, visibilidade e melhor aproveitamento das oportunidades disponíveis no mercado público.</p>
      <p style="margin:0;font-size:14px;line-height:1.55;color:#334155;">O <span style="color:#16a34a;font-weight:800;">i-Ganhei</span> contribui para uma operação mais preparada para crescimento, tomada de decisão estratégica e evolução contínua da gestão comercial.</p>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;gap:12px;min-width:0;min-height:0;">
      <div style="display:flex;gap:10px;align-items:flex-start;padding:14px;background:#ffffff;border:1.5px solid #bbf7d0;border-radius:14px;box-shadow:0 6px 14px -8px rgba(34,197,94,.28);"><div style="width:38px;height:38px;border-radius:12px;border:2px solid #22c55e;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:#f0fdf4;"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M7 14l4-4 4 4 5-6"/></svg></div><div><div style="font-size:14px;font-weight:900;color:#064e3b;">Produtividade</div><div style="font-size:12px;color:#475569;line-height:1.35;margin-top:4px;">Menos atividades manuais e retrabalho.</div></div></div>
      <div style="display:flex;gap:10px;align-items:flex-start;padding:14px;background:#ffffff;border:1.5px solid #bbf7d0;border-radius:14px;box-shadow:0 6px 14px -8px rgba(34,197,94,.28);"><div style="width:38px;height:38px;border-radius:12px;border:2px solid #22c55e;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:#f0fdf4;"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/></svg></div><div><div style="font-size:14px;font-weight:900;color:#064e3b;">Previsibilidade</div><div style="font-size:12px;color:#475569;line-height:1.35;margin-top:4px;">Visão clara sobre oportunidades e evolução.</div></div></div>
      <div style="display:flex;gap:10px;align-items:flex-start;padding:14px;background:#ffffff;border:1.5px solid #bbf7d0;border-radius:14px;box-shadow:0 6px 14px -8px rgba(34,197,94,.28);"><div style="width:38px;height:38px;border-radius:12px;border:2px solid #22c55e;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:#f0fdf4;"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a9 9 0 1 1-9-9"/><path d="M21 3v6h-6"/></svg></div><div><div style="font-size:14px;font-weight:900;color:#064e3b;">Eficiência</div><div style="font-size:12px;color:#475569;line-height:1.35;margin-top:4px;">Processos organizados e ágeis.</div></div></div>
      <div style="display:flex;gap:10px;align-items:flex-start;padding:14px;background:#ffffff;border:1.5px solid #bbf7d0;border-radius:14px;box-shadow:0 6px 14px -8px rgba(34,197,94,.28);"><div style="width:38px;height:38px;border-radius:12px;border:2px solid #22c55e;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:#f0fdf4;"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2l3 7h7l-5.5 4.5L18 21l-6-4-6 4 1.5-7.5L2 9h7z"/></svg></div><div><div style="font-size:14px;font-weight:900;color:#064e3b;">Escala</div><div style="font-size:12px;color:#475569;line-height:1.35;margin-top:4px;">Operação preparada para crescer.</div></div></div>
    </div>
  </div>
</div>'::text AS html4,
    '<div style="box-sizing:border-box;width:100%;height:100%;margin:0;padding:34px 44px 32px;border-radius:18px;overflow:hidden;border:1px solid #22c55e;box-shadow:0 0 0 1px rgba(34,197,94,.08),0 8px 24px -12px rgba(34,197,94,.25);font-family:Inter,system-ui,sans-serif;background:linear-gradient(135deg,#0a1628 0%,#0f1f3d 60%,#0a1f2e 100%);color:#ffffff;display:flex;flex-direction:column;gap:18px;position:relative;">
  <div style="display:inline-flex;align-items:center;gap:6px;background:#22c55e;color:#fff;padding:6px 14px;border-radius:999px;font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;width:max-content;"><span style="width:6px;height:6px;border-radius:50%;background:#fff;opacity:.9;"></span>Implementação e Investimento</div>
  <div style="display:flex;flex-direction:column;gap:8px;">
    <h2 style="font-size:26px;margin:0;font-weight:800;letter-spacing:-.02em;line-height:1.15;color:#fff;text-transform:uppercase;">Uma jornada estruturada para sua <span style="color:#22c55e;">operação evoluir</span></h2>
    <p style="margin:0;font-size:13.5px;line-height:1.55;color:rgba(255,255,255,.78);max-width:980px;">A implementação do i-Ganhei é conduzida de forma alinhada às características operacionais de cada empresa, garantindo uma transição segura, organizada e aderente às necessidades da operação.</p>
  </div>
  <div style="flex:1;min-height:0;display:grid;grid-template-rows:1fr 1fr;gap:16px;">
    <div style="display:flex;flex-direction:column;gap:8px;min-height:0;">
      <div style="display:flex;align-items:center;gap:10px;"><div style="height:1px;flex:1;background:rgba(34,197,94,.4);"></div><div style="font-size:11px;font-weight:800;color:#22c55e;letter-spacing:.18em;text-transform:uppercase;">Jornada de Implementação</div><div style="height:1px;flex:1;background:rgba(34,197,94,.4);"></div></div>
      <div style="flex:1;min-height:0;display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;">
        <div style="padding:12px;background:rgba(255,255,255,.04);border:1px solid rgba(34,197,94,.3);border-radius:14px;display:flex;flex-direction:column;align-items:center;text-align:center;justify-content:center;gap:6px;position:relative;"><div style="position:absolute;top:8px;left:8px;width:22px;height:22px;border-radius:50%;background:#22c55e;color:#fff;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:800;">01</div><div style="font-size:13px;font-weight:800;color:#fff;line-height:1.2;">Diagnóstico Operacional</div><div style="font-size:11px;color:#94a3b8;line-height:1.4;">Mapeamento do cenário, processos e estrutura atual.</div></div>
        <div style="padding:12px;background:rgba(255,255,255,.04);border:1px solid rgba(34,197,94,.3);border-radius:14px;display:flex;flex-direction:column;align-items:center;text-align:center;justify-content:center;gap:6px;position:relative;"><div style="position:absolute;top:8px;left:8px;width:22px;height:22px;border-radius:50%;background:#22c55e;color:#fff;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:800;">02</div><div style="font-size:13px;font-weight:800;color:#fff;line-height:1.2;">Estruturação da Solução</div><div style="font-size:11px;color:#94a3b8;line-height:1.4;">Configuração e parametrização alinhadas às necessidades.</div></div>
        <div style="padding:12px;background:rgba(255,255,255,.04);border:1px solid rgba(34,197,94,.3);border-radius:14px;display:flex;flex-direction:column;align-items:center;text-align:center;justify-content:center;gap:6px;position:relative;"><div style="position:absolute;top:8px;left:8px;width:22px;height:22px;border-radius:50%;background:#22c55e;color:#fff;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:800;">03</div><div style="font-size:13px;font-weight:800;color:#fff;line-height:1.2;">Organização e Acompanhamento</div><div style="font-size:11px;color:#94a3b8;line-height:1.4;">Entrada em operação com direcionamento contínuo.</div></div>
      </div>
    </div>
    <div style="display:flex;flex-direction:column;gap:8px;min-height:0;">
      <div style="display:flex;align-items:center;gap:10px;"><div style="height:1px;flex:1;background:rgba(34,197,94,.4);"></div><div style="font-size:11px;font-weight:800;color:#22c55e;letter-spacing:.18em;text-transform:uppercase;">Investimento</div><div style="height:1px;flex:1;background:rgba(34,197,94,.4);"></div></div>
      <div style="flex:1;min-height:0;display:grid;grid-template-columns:1fr 1fr;gap:12px;">
        <div style="padding:14px 16px;background:rgba(255,255,255,.04);border:1px solid rgba(34,197,94,.3);border-radius:14px;display:flex;flex-direction:column;justify-content:center;gap:6px;"><div style="font-size:14px;font-weight:800;color:#22c55e;">Implantação Estratégica</div><div style="font-size:12px;color:rgba(255,255,255,.78);line-height:1.45;">Estruturação inicial da operação, parametrizações e direcionamentos para entrada em operação.</div></div>
        <div style="padding:14px 16px;background:rgba(255,255,255,.04);border:1px solid rgba(34,197,94,.3);border-radius:14px;display:flex;flex-direction:column;justify-content:center;gap:6px;"><div style="font-size:14px;font-weight:800;color:#22c55e;">Plataforma i-Ganhei</div><div style="font-size:12px;color:rgba(255,255,255,.78);line-height:1.45;">Disponibilização contínua da solução, acompanhamento operacional e evolução da plataforma.</div></div>
      </div>
    </div>
  </div>
</div>'::text AS html5
)
UPDATE proposal_templates t
SET blocks = (
  SELECT jsonb_agg(
    CASE
      WHEN ord = 4 THEN jsonb_set(elem, '{html}', to_jsonb((SELECT html4 FROM new_slides)))
      WHEN ord = 5 THEN jsonb_set(elem, '{html}', to_jsonb((SELECT html5 FROM new_slides)))
      ELSE elem
    END
    ORDER BY ord
  )
  FROM jsonb_array_elements(t.blocks) WITH ORDINALITY AS x(elem, ord)
),
updated_at = now()
WHERE t.id = '9ac64afe-2213-4ceb-89c0-1bad0b83df87';
